={{ (() => {
  const text = $('Analyser la page Google Flow').item.json.content[0].text;
  const lines = text.split('\n');

  const index = lines.findIndex(line =>
    line.includes('StaticText "Que voulez-vous créer')
  );

  if (index === -1) return '';

  const nextLine = lines
    .slice(index + 1, index + 4)
    .find(line => /uid=([^\s]+)/.test(line));

  return nextLine?.match(/uid=([^\s]+)/)?.[1] ?? '';
})() }}

