const items = $input.all();

return items.map((item, index) => ({
  json: {
    index,
    text: item.json.content?.[0]?.text ?? '',
  }
}));

const text = $input.first().json.content?.[0]?.text ?? '';

return {
  json: {
    textStart: text.substring(0, 1000),
    hasDataUri: text.includes('data:'),
    hasImageData: text.includes('data:image/'),
    hasHtmlData: text.includes('data:text/html')
  }
};

const narrationsSource = $('Liste des 20 prompts').first().json.narrations;

return $input.all().map((item) => {
  const sceneIndex = (item.json.scene || item.json.index || 1) - 1;
  return {
    json: {
      ...item.json,
      narration: narrationsSource[sceneIndex] || narrationsSource[narrationsSource.length - 1]
    },
    binary: item.binary
  };
});
